import sharp from "sharp"
import { expect, test } from "bun:test"
import { Circuit } from "tscircuit-latest"
import { CircuitJsonToKicadPcbConverter } from "lib/pcb/CircuitJsonToKicadPcbConverter"
import { convertCircuitJsonToPcbSvg } from "circuit-to-svg"

// Input is generated by core, then given the already-published Circuit JSON
// tenting fields because this repository's pinned core predates that TSX API.
test("KiCad vias inherit their own board defaults and retain explicit overrides", async () => {
  const circuit = new Circuit()
  circuit.add(
    <panel width={24} height={12}>
      {[
        { name: "TOP", x: -6 },
        { name: "BOTTOM", x: 6 },
      ].map(({ name, x }) => (
        <board
          key={name}
          name={name}
          width={10}
          height={10}
          pcbX={x}
          routingDisabled
        >
          <pcbnotetext
            text={`${name}: inherited / exposed / override`}
            pcbY={3}
            fontSize={0.4}
          />
          <via
            name="INHERITED"
            pcbX={-2}
            holeDiameter={0.3}
            outerDiameter={0.6}
          />
          <via name="EXPOSED" pcbX={0} holeDiameter={0.3} outerDiameter={0.6} />
          <via
            name="OVERRIDE"
            pcbX={2}
            holeDiameter={0.3}
            outerDiameter={0.6}
          />
        </board>
      ))}
    </panel>,
  )
  await circuit.renderUntilSettled()
  const circuitJson = circuit.getCircuitJson()
  const boardGroups = circuitJson
    .filter((element) => element.type === "source_group")
    .filter((group) => ["TOP", "BOTTOM"].includes(group.name ?? ""))
  const boards = circuitJson.filter((element) => element.type === "pcb_board")
  for (const [boardIndex, board] of boards.entries()) {
    Object.assign(board, {
      subcircuit_id: boardGroups[boardIndex]!.subcircuit_id,
      default_via_tented_on_top: boardIndex === 0,
      default_via_tented_on_bottom: boardIndex === 1,
    })
    const vias = circuitJson.filter(
      (element) =>
        element.type === "pcb_via" &&
        element.subcircuit_id === boardGroups[boardIndex]!.subcircuit_id,
    )
    Object.assign(vias[1]!, { tented_on_top: false, tented_on_bottom: false })
    Object.assign(vias[2]!, {
      tented_on_top: boardIndex === 1,
      tented_on_bottom: boardIndex === 0,
    })
  }
  const converter = new CircuitJsonToKicadPcbConverter(circuitJson)
  converter.runUntilFinished()
  const output = converter.getOutputString()
  const viaNodes = output.match(/\(via\s[\s\S]*?(?=\n  \(|\n\))/g) ?? []
  const statuses = viaNodes
    .map(
      (via, viaIndex) =>
        `<text x="20" y="${25 + viaIndex * 20}" fill="#ffd166" font-family="sans-serif" font-size="16">Via ${viaIndex + 1}: ${via.match(/\(tenting[^\n]*\)/)?.[0] ?? "no exported tenting"}</text>`,
    )
    .join("")
  const svg = convertCircuitJsonToPcbSvg(circuitJson, {
    width: 1200,
    height: 900,
  }).replace("</svg>", `${statuses}</svg>`)
  await expect(sharp(Buffer.from(svg)).png().toBuffer()).toMatchPngSnapshot(
    import.meta.path,
  )
  expect(viaNodes).toHaveLength(6)
  expect(viaNodes.map((via) => via.match(/\(tenting[^\n]*\)/)?.[0])).toEqual([
    "(tenting (front yes) (back no))",
    "(tenting (front no) (back no))",
    "(tenting (front no) (back yes))",
    "(tenting (front no) (back yes))",
    "(tenting (front no) (back no))",
    "(tenting (front yes) (back no))",
  ])
})
